// Package: Microsoft.Extensions.AI + Azure.AI.Search + Npgsql
// Complete RAG pipeline demonstrating all six stages in a C# backend.

using Microsoft.Extensions.AI;
using Azure.AI.Search;
using Azure.AI.Search.Models;
using Npgsql;

public sealed class RagPipeline
{
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embedder;
    private readonly SearchClient _searchClient;
    private readonly IChatClient _chatClient;
    private const string ConnectionString = "Host=localhost;Database=ragdb;Username=postgres;Password=postgres";

    public RagPipeline(
        IEmbeddingGenerator<string, Embedding<float>> embedder,
        SearchClient searchClient,
        IChatClient chatClient)
    {
        _embedder = embedder ?? throw new ArgumentNullException(nameof(embedder));
        _searchClient = searchClient ?? throw new ArgumentNullException(nameof(searchClient));
        _chatClient = chatClient ?? throw new ArgumentNullException(nameof(chatClient));
    }

    public async Task IngestAsync(string documentText, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(documentText);

        var chunks = documentText.Split(new[] { ". " }, StringSplitOptions.RemoveEmptyEntries);
        var embeddings = new List<GeneratedEmbedding<Embedding<float>>>();

        await foreach (var embedding in _embedder.GenerateAsync(chunks, ct))
        {
            embeddings.Add(embedding);
        }

        await using var connection = new NpgsqlConnection(ConnectionString);
        await connection.OpenAsync(ct);

        await using var transaction = await connection.BeginTransactionAsync(ct);

        foreach (var (chunk, embedding) in chunks.Zip(embeddings))
        {
            await using var cmd = new NpgsqlCommand(
                "INSERT INTO document_chunks (text, embedding) VALUES (@text, @embedding)",
                connection,
                transaction);

            cmd.Parameters.AddWithValue("text", chunk);
            cmd.Parameters.AddWithValue("embedding", NpgsqlDbType.Vector, embedding.Vector.ToArray());

            await cmd.ExecuteNonQueryAsync(ct);
        }

        await transaction.CommitAsync(ct);
    }

    public async Task<string> QueryAsync(string question, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(question);

        var queryResult = await _embedder.GenerateAsync(question, ct);
        var queryVector = queryResult.Vector.ToArray();

        var options = new SearchOptions
        {
            Size = 5,
            VectorSearch = new VectorSearchOptions
            {
                Queries = { new VectorizedQuery(queryVector) { KNearestNeighborsCount = 5 } }
            }
        };

        var response = await _searchClient.SearchAsync<DocumentChunkProjection>(
            "*",
            options,
            ct);

        var context = new System.Text.StringBuilder();
        await foreach (var result in response.Value.GetResultsAsync(ct))
        {
            context.AppendLine(result.Document.Text);
            context.AppendLine("---");
        }

        var prompt = $"""
Answer the question using only the context below.

Context:
{context}

Question:
{question}
""";

        var result = await _chatClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            ct);

        return result.Messages.Last().Text ?? string.Empty;
    }
}

public sealed record DocumentChunkProjection(string Text);

